/* Start of a walker group: lists the group's mobys and spaces them along the path in random order. */
void initialize_path_walker_group(unsigned char *m) {
    unsigned char *objects[16];
    unsigned char *previous;
    L16WalkerData *d = ((L16WalkerData *)((Moby *)m)->pvars);
    short *list = kalebo3_moby_groups[((Moby *)m)->group];
    short count = 0, rank;
    int i;
    float period;

    if (list == 0 || d->path_index == -1) {
        return;
    }
    period = (float)*(int *)kalebo3_path_table[d->path_index] - 1.0f;
    do {
        objects[count] = (unsigned char *)(kalebo3_moby_array + ((*(unsigned short *)list & 0x7FFF) << 8));
        count++;
    } while (*list++ >= 0);
    previous = objects[count - 1];
    rank = count;
    for (i = 0; i < count; i++) {
        unsigned char *current;
        L16WalkerData *data;
        unsigned short flags;

        if (i == count - 1) {
            /* the last one takes the slot the loop index is on */
            current = objects[i];
        } else {
            /* the others take a random slot, or the next one still in use after it */
            int selected = random_integer_below(count - 1);

            for (;;) {
                if (objects[selected] != 0) {
                    current = objects[selected];
                    objects[selected] = 0;
                    break;
                }
                selected = (selected + 1) % (count - 1);
            }
        }
        flags = path_walker_draw_distance;
        ((Moby *)current)->update_dist = 255;
        ((Moby *)current)->scale *= path_walker_initial_scale_multiplier;
        *(int *)&((Moby *)current)->collision = 0;
        *(unsigned short *)&((Moby *)current)->draw_dist = flags;
        data = ((L16WalkerData *)((Moby *)current)->pvars);
        data->parameter = (float)rank * (period / IntToFloat(count));
        data->owner = previous;
        data->period = period;
        previous = current;
        data->height_step = random_float_between(path_walker_height_range_start, path_walker_height_range_end);
        data->speed = random_float_between(path_walker_speed_range_start, path_walker_speed_range_end) * g_frame_time;
        data->target_speed = data->speed;
        ((Moby *)current)->state = 1;
        rank--;
    }
}
