/* Moves the platform between two heights above its joint, with a particle while it moves. */
void ElevatorPlatformUpdate(Moby *m) {
    L16PlatformVector delta, old_rotation, motion;
    L16PlatformData *d = (L16PlatformData *)m->pvars;
    float *position = (float *)&m->pos;
    float *rotation = (float *)&m->rot;

    FastVecScale(delta.v, position, -1.0f);
    qcopy(old_rotation.v, rotation);
    if (d) {
        switch (m->state) {
        case 0:
            motion.q = 0;
            motion.v[2] = 1.0f;
            d->particle = -1;
            matrix_mul_vec3(motion.v, motion.v, kalebo3_level_cylinders + (d->joint << 7));
            d->goal = motion.v[2] + *(float *)(kalebo3_level_cylinders + d->joint * 0x80 + 0x38);
            m->pos.z = motion.v[2] + *(float *)(kalebo3_level_cylinders + d->joint * 0x80 + 0x38) + elevator_height_offset;
            m->command = 1;
            m->state = 2;
            break;
        case 2:
            if (Sound_IsPlaying(m, d->particle)) {
                Sound_StopSlot(d->particle);
                d->particle = -1;
            }
            if (vec_distance_xy(position, g_hero.motion.pos.f) < 20.0f) {
                clear_u64_value(motion.v);
                if (m->command) {
                    motion.v[2] = -1.0f;
                } else {
                    motion.v[2] = 1.0f;
                }
                transform_vector(motion.v, motion.v, kalebo3_level_cylinders + (d->joint << 7));
                motion.v[2] = motion.v[2] + *(float *)(kalebo3_level_cylinders + d->joint * 0x80 + 0x38) + elevator_height_offset;
                if (FastAbsF(g_hero.motion.pos.f[2] - motion.v[2]) < 1.0f) {
                    m->command = (m->command + 1) & 1;
                    d->goal = motion.v[2];
                    d->speed = 0.0f;
                    m->state = 3;
                    break;
                }
            }
            if (g_hero.ground_moby == m && g_hero.air_frames.s == 0) {
                clear_u64_value(motion.v);
                if (m->command) {
                    motion.v[2] = -1.0f;
                } else {
                    motion.v[2] = 1.0f;
                }
                m->command = (m->command + 1) & 1;
                transform_vector(motion.v, motion.v, kalebo3_level_cylinders + (d->joint << 7));
                d->goal = motion.v[2] + *(float *)(kalebo3_level_cylinders + d->joint * 0x80 + 0x38) + elevator_height_offset;
                d->speed = 0.0f;
                m->state = 3;
            }
            break;
        case 3: {
            float *hero_position = g_hero.motion.pos.f;
            float speed;

            if (vec_distance_xy(hero_position, kalebo3_level_cylinders + (d->joint << 7) + 0x30) > 2.25f
                || FastAbsF(m->pos.z - hero_position[2] - 2.0f) > 1.0f
                || m->pos.z < d->goal) {
                speed = ApproachWithVelocity(&m->pos.z, &d->speed, d->goal,
                                      elevator_height_acceleration * g_frame_time_sq, elevator_height_acceleration * g_frame_time_sq,
                                      *(float *)&elevator_max_speed * g_frame_time);
            } else {
                speed = ApproachWithVelocity(&m->pos.z, &d->speed, m->pos.z,
                                      elevator_height_acceleration * 4.0f * g_frame_time_sq, elevator_height_acceleration * 4.0f * g_frame_time_sq,
                                      *(float *)&elevator_max_speed * g_frame_time);
            }
            clear_u64_value(motion.v);
            motion.v[2] = speed;
            update_entity_matrix((char *)d->basis, motion.v, &m->rot, &m->rot);
            if (motion.v[2] != 0.0f) {
                if (!Sound_IsPlaying(m, d->particle)) {
                    d->particle = Moby_PlaySound(0, 4, (int)m);
                }
            } else if (Sound_IsPlaying(m, d->particle)) {
                Sound_StopSlot(d->particle);
                d->particle = -1;
            }
            if (m->pos.z == d->goal && (g_hero.ground_moby != m || g_hero.air_frames.s != 0)) {
                clear_u64_value(d->basis[1]);
                m->state = 2;
                break;
            }
            if (d->speed != 0.0f) {
                AddDrawCallback(DrawRingStack, m);
            }
            break;
        }
        }
        FastVecAdd(delta.v, delta.v, &m->pos);
        update_entity_matrix((char *)d->basis, delta.v, old_rotation.v, &m->rot);
    }
}
