/* Repositions a target at random intervals while the hero is in the clip volume. */
void update_target_reposition_cycle(char *moby) {
    char *g = hero_globals_base + 0xE9D;
    char *data = ((char *)((Moby *)moby)->pvars);
    char *target;
    int n;
    float pos[4];
    if (!is_point_inside_clip_volume(g, *(int *)(data + 8))) return;
    target = kalebo3_moby_array + (*(int *)(data + 4) << 8);
    switch ((unsigned char)moby[0x20]) {
    case 0:
        moby[0x20] = 1;
        *(int *)(data + 0xC) = scale_ticks(rand_range(0xB4, 0x168));
        break;
    case 1:
        if (vec_distance_xy(g, target + 0x10) > 3.0f) {
            if (find_group_class_010e_moby_in_state_6(*(int *)data) != 0) {
                if (fast_dec_timer(data + 0xC)) {
                    moby[0x20] = 2;
                    request_target_reposition(target);
                    *(int *)(data + 0xC) = scale_ticks(rand_range(0xB4, 0x168));
                }
            }
        }
        break;
    case 2:
        n = get_target_reposition_status(target);
        switch (n) {
        case 0:
            moby[0x20] = 1;
            break;
        case 2:
            moby[0x20] = 1;
        {
            char *other = find_group_class_010e_moby_in_state_6(*(int *)data);
            if (other != 0) {
                qcopy(pos, target + 0x10);
                pos[2] += 1.0f;
                pos[2] = ProbeGroundHeight(pos, 0, 0.5f);
                reposition_moby_with_collision_check(other, pos);
            }
        }
            break;
        }
        break;
    }
}
