// Finds the first moby of type 0x10E in a level's id list that passes the check.
char *find_group_class_010e_moby_in_state_6(int idx)
{
    short *p = kalebo3_moby_groups[idx];
    char *moby;
    if (p == 0)
        return 0;
    for (;;) {
        moby = kalebo3_moby_array + ((*(unsigned short *)p & 0x7FFF) << 8);
        if (*(short *)(moby + 0xA6) == 0x10E && is_moby_in_state_6(moby))
            return moby;
        if (*p++ < 0)
            return 0;
    }
}
extern float FastVecDot(void *, void *);

/* For each of n point pairs, reflects a direction and writes its 2D map coordinates. */
void compute_level16_reflection_map_coordinates(int n, Vec3f *p1, Vec3f *p2, int unused, float *out) {
    int i;
    float a[4];
    float v[4];
    float t[4];
    float w[4];

    for (i = 0; i < n; i++) {
        float d;
        float len;

        v[3] = 1.0f;
        v[0] = p2[i].x;
        v[1] = p2[i].y;
        v[2] = p2[i].z;
        FastVecSub(a, v, kalebo3_camera_pos);
        vec_scale_to_length(a, a, 1.0f);
        w[3] = 1.0f;
        w[0] = p1[i].x;
        w[1] = p1[i].y;
        w[2] = p1[i].z;
        vec_scale_to_length(w, w, 1.0f);
        d = FastVecDot(w, a);
        FastVecScale(t, w, d + d);
        FastVecSub(t, a, t);
        vec_scale_to_length(t, t, 1.0f);
        t[2] = t[2] + 1.0f;
        len = FastVecLength(t);
        len = len + len;
        out[i * 2] = (t[0] / len + 0.5f) * 2.0f;
        out[i * 2 + 1] = (t[1] / len + 0.5f) * 2.0f;
    }
}
